"Каждый осколок Алатыря, найденный любым Ловчим, — в разломах и у хранителей-старейшин Капищ, — ложится в общий камень Ордена. Собрана грань — дорога в её мир распутана: {0} дня духи этой мифологии встречаются в {1} раза чаще, у всех Ловчих разом. Собраны все грани сезона — приходит Кощей: {2} дней он ждёт во всех Разломах мира, а потом раскалывает камень. Из трещины выходит новая мифология, начинается новый сезон — и в Лиге тоже. В новом сезоне у камня на одну грань больше.":"Chaque éclat d'Alatyr trouvé par n'importe quel Chasseur — dans les failles et auprès des gardiens anciens des Kapishche — rejoint la pierre commune de l'Ordre. Une facette reconstituée démêle la route de son monde : pendant {0} jours, les esprits de cette mythologie apparaissent {1} fois plus souvent, pour tous les Chasseurs à la fois. Quand toutes les facettes de la saison sont reconstituées, Koschei arrive : pendant {2} jours il attend dans toutes les Failles du monde, puis il brise la pierre. Une nouvelle mythologie sort de la fissure et une nouvelle saison commence — dans la Ligue aussi. Dans la nouvelle saison, la pierre a une facette de plus.",
