"Китай, Корея, Япония и Юго-Восточная Азия":"Chine, Corée, Japon et Asie du Sud-Est",
"Ацтекская":"Aztèque",
"Америка — от Аляски до Огненной Земли":"Les Amériques — de l'Alaska à la Terre de Feu",
"Оберег":"Talisman",
"Узелок с заговорённой травой. Бросай в духа, чтобы поймать.":"Un petit baluchon d'herbes enchantées. Lance-le sur un esprit pour l'attraper.",
"Серебряный оберег":"Talisman d'argent",
"Серебро держит духов крепче. Шанс поимки ×1,5.":"L'argent retient mieux les esprits. Chances de capture ×1,5.",
"Золотой оберег":"Talisman d'or",
"Лучший оберег Ордена. Шанс поимки ×2.":"Le meilleur talisman de l'Ordre. Chances de capture ×2.",
"Духи обожают мёд. Успокаивает духа: шанс поимки ×1,5 на один бросок.":"Les esprits adorent le miel. Calme l'esprit : chances de capture ×1,5 pour un lancer.",
"Подорожник":"Plantain",
"Лист к ране — и полегчало. Возвращает духу четверть здоровья.":"Une feuille sur la plaie, et ça va mieux. Rend un quart de sa santé à l'esprit.",
"Целебный отвар":"Décoction curative",
"Травы Велеса, сваренные в воде из источника. Возвращает духу 60% здоровья.":"Des herbes de Veles bouillies dans l'eau de source. Rend 60 % de sa santé à l'esprit.",
"Мёртвая вода":"Myortvaya Voda",
"Редкая сказочная вода, что сращивает самые тяжкие раны. Дух без сил поднимется на 4 часа раньше. Живых не лечит.":"Une rare eau de conte qui referme les plaies les plus graves. Un esprit épuisé se relève 4 h plus tôt. Ne soigne pas les esprits encore debout.",
"Живая вода":"Zhivaya Voda",
"Возвращает духу половину здоровья, а в разломе — лечит прямо в бою. Духа без сил не поднимет.":"Rend à l'esprit la moitié de sa santé et, dans une faille, soigne en plein combat. Ne relève pas un esprit épuisé.",
"Ладан":"Encens",
"Дымок приманивает духов: 30 минут их вокруг вдвое больше.":"La fumée attire les esprits : pendant 30 minutes, il y en a deux fois plus autour de toi.",
"Дальний пропуск":"Passe lointain",
"Грамота Ордена: закрыть Разлом до 5 км от тебя, не подходя к нему. Один Орден дарит каждый день.":"Un sauf-conduit de l'Ordre : ferme une Faille jusqu'à 5 km de toi sans t'en approcher. L'Ordre en offre un chaque jour.",
"Кольцо Ордена с воронкой дорог: шагни в любое место Атласа мира сразу, не дожидаясь перезарядки. Одни Врата дарят на седьмой день серии.":"Un anneau de l’Ordre avec un tourbillon de routes : va tout de suite n’importe où dans l’Atlas du monde, sans attendre le temps de recharge. Une est offerte le septième jour de la série.",
"Настой опыта":"Tisane d'XP",
"Медовый настой на травах Велеса: сутки опыта на четверть больше.":"Tisane au miel et aux herbes de Veles : un quart d'XP en plus pendant 24 h.",
"Подарок":"Cadeau",
"Узелок для друга: обереги, мёд, иногда кокон. Отправляется в «Меню → Друзья», раз в день каждому.":"Un baluchon pour un ami : talismans, miel, parfois un cocon. À envoyer depuis « Menu → Amis », une fois par jour à chacun.",
