"Быстрота и отвага":"Vitesse et audace",
"Наследники княжеских дружин под знаком сокола-Рарога. Когда Кощей расколол Алатырь, они первыми встали у Капищ и держат Навь громом Перуна.":"Héritiers des troupes des princes, sous le signe du faucon Rarog. Quand Koschei a brisé Alatyr, ils ont été les premiers à se dresser devant les Kapishches, et ils contiennent la Nav par le tonnerre de Péroun.",
