"Щит к щиту":"Bouclier contre bouclier",
"Ловчие, что сомкнули щиты под знаком совы Афины. В Перепутицу они стерегут храмы, чтобы тени Аида не вышли к живым.":"Des Chasseurs qui ont serré les boucliers sous le signe de la chouette d'Athéna. Pendant le Grand Embrouillamini, ils gardent les temples pour que les ombres d'Hadès ne sortent pas parmi les vivants.",
