"Верные, как волки Одина. Хирд стоит у рунных камней, пока не затянутся трещины к Гиннунгагапу.":"Fidèles comme les loups d'Odin. Le hird se tient près des pierres runiques jusqu'à ce que les failles vers le Ginnungagap se referment.",
