"Друиды и воины священных рощ под рукой медведицы Артио. Братство держит каменные круги, чтобы холмы сидов не распахнулись навсегда.":"Druides et guerriers des bois sacrés, sous la patte de l'ourse Artio. La confrérie tient les cercles de pierres pour que les tertres des sidhe ne s'ouvrent pas à jamais.",
"Стражи Дуата":"Gardiens de la Douat",
