"Солнце взойдёт снова":"Le soleil se lèvera encore",
"Хранители солнечной ладьи Ра. Пока Алатырь расколот, стражи стоят у обелисков, чтобы ночь Дуата не поглотила рассвет.":"Gardiens de la barque solaire de Rê. Tant qu'Alatyr est brisée, ils veillent près des obélisques pour que la nuit de la Douat n'engloutisse pas l'aube.",
"Небесная Гвардия":"Garde céleste",
"Дракон":"Dragon",
"гвардеец":"garde",
