"Ученик":"Apprenti",
"Мастер":"Maître",
"Старейшина":"Ancien",
"Святки":"Svyatki",
"Зимние праздники: Морозко и Снегурка выходят к людям, духи Ветра и Воды встречаются чаще, в источниках — подарки.":"Fêtes d'hiver : Morozko et Snegurka sortent à la rencontre des gens, les esprits de Vent et d'Eau sont plus fréquents, et les sources offrent des cadeaux.",
"Масленица":"Maslenitsa",
"Провожаем зиму! Духи Огня встречаются вдвое чаще, в источниках много мёда («блинов»), опыт ×1,5.":"Adieu l'hiver ! Les esprits de Feu sont deux fois plus fréquents, les sources regorgent de miel (les « blinis »), XP ×1,5.",
"Купальская ночь":"Nuit de Kupala",
"Цветёт папоротник: Купалинка повсюду, духи Огня, Воды и Леса чаще, ночью сияющие — вдвое чаще.":"La fougère fleurit : Kupalinka est partout, les esprits de Feu, d'Eau et de Forêt sont plus fréquents, et la nuit, les scintillants deux fois plus.",
"Покров":"Pokrov",
"Первые туманы и иней: духи Ветра и Воды встречаются чаще, Листопадница — повсюду, в источниках больше добычи.":"Premières brumes et premier givre : les esprits de Vent et d'Eau sont plus fréquents, Listopadnitsa est partout, et les sources donnent plus de butin.",
"Велесова ночь":"Nuit de Veles",
"Граница миров тоньше всего: духи Тени втрое чаще, в великих разломах ждёт Кощей, сияющие Тени вдвое чаще.":"La frontière entre les mondes est au plus mince : esprits d'Ombre trois fois plus fréquents, Koschei attend dans les Grandes failles, Ombres scintillantes deux fois plus fréquentes.",
"Этот источник теперь принадлежит Нави!":"Cette source appartient désormais à la Nav !",
"Твои духи будут служить Кощею!":"Tes esprits serviront Koschei !",
