"Усилен погодой":"Boosté par la météo",
"Омрачённый Навью":"Assombri par la Nav",
"Фото":"Photo",
"Коснись оберега — он полетит в духа.":"Touche le talisman — il volera vers l'esprit.",
"Смахни оберег вверх.":"Lance le talisman vers le haut.",
"Попади в кольцо, когда оно маленькое!":"Vise le cercle quand il est petit !",
"Сияющий дух!":"Esprit scintillant !",
"<b>Зажми оберег и смахни вверх</b>, прямо к духу.<br>Чем быстрее свайп — тем дальше бросок.":"<b>Maintiens le talisman et lance-le vers le haut</b>, droit sur l'esprit.<br>Plus le geste est rapide, plus le lancer va loin.",
"Есть только «{0}»":"Tu n'as que « {0} »",
"Нет оберегов":"Pas de talismans",
"Дух уже лакомится мёдом":"L'esprit savoure déjà le miel",
"Мёда нет. Его можно найти у источников.":"Pas de miel. Tu en trouveras aux sources.",
"Дух ест мёд и успокаивается":"L'esprit mange le miel et se calme",
"Обереги этого вида закончились":"Plus de talismans de ce type",
"Мимо!":"Raté !",
"Обереги закончились!":"Plus de talismans !",
"Обереги кончились — дух вернулся в Навь…":"Plus de talismans — l'esprit est retourné dans la Nav…",
"Дух вырвался!":"L'esprit s'est échappé !",
"Почти получилось!":"Presque !",
"Ай! Вырвался!":"Aïe ! Il s'est échappé !",
"Пойман!":"Attrapé !",
"Новая запись в Бестиарии!":"Nouvelle entrée au Bestiaire !",
"Сияющий дух — редкая удача!":"Esprit scintillant — quelle chance !",
