"(Звездопад ×2)":"(Pluie d'étoiles ×2)",
"<b>+{0}</b> искр":"<b>+{0}</b> étincelles",
"<b>+{0}</b> эссенции «{1}»":"<b>+{0}</b> essence « {1} »",
"Духолов · Ловчий {0} · {1}":"Dukholov · Chasseur {0} · {1}",
"Не удалось сделать снимок":"Impossible de prendre la photo",
"Камера недоступна — AR выключен":"Caméra indisponible — RA désactivée",
"Уйти?":"Partir ?",
"Если уйти, дух из разлома будет потерян.":"Si tu pars, l'esprit de la faille sera perdu.",
"Нет координат или времени снимка":"Pas de coordonnées ni d'heure dans la photo",
"Не JPEG":"Pas un JPEG",
"Ты и {0} теперь друзья! Стартовый подарок уже в сумке.":"Toi et {0}, vous êtes maintenant amis ! Le cadeau de bienvenue est déjà dans ton sac.",
"Лови духов вместе со мной в «Духолове»! Открой ссылку — мы сразу станем друзьями, а тебе достанется стартовый подарок:\n{0}":"Attrape des esprits avec moi dans « Dukholov » ! Ouvre le lien — on deviendra amis tout de suite, et tu recevras un cadeau de bienvenue :\n{0}",
"Код повреждён — скопируй его целиком":"Code endommagé — copie-le en entier",
"Не удалось прочитать код":"Impossible de lire le code",
"Новый друг: {0} — вы теперь в друзьях друг у друга":"Nouvel ami : {0} — vous êtes maintenant amis",
"Тебе пришли подарки: {0}. Открой «Меню → Друзья»":"Tu as reçu des cadeaux : {0}. Ouvre « Menu → Amis »",
"В коде ошибка":"Erreur dans le code",
"{0} теперь в друзьях!":"{0} est maintenant ton ami !",
"Данные друга {0} обновлены":"Les données de ton ami {0} ont été mises à jour",
"Подарки теперь приходят сами — загляни в «Друзья»":"Les cadeaux arrivent désormais tout seuls — jette un œil à « Amis »",
"Передача духов по коду закрыта — продавай и покупай духов на Аукционе":"Le transfert d'esprits par code est fermé — achète et vends des esprits aux Enchères",
"Не похоже на код Духолова":"Ça ne ressemble pas à un code Dukholov",
