"ДРУЗЕЙ":"AMIS",
"Подарков в сумке: {0}":"Cadeaux dans le sac : {0}",
"Позвать":"Inviter",
"Позвать друга по ссылке":"Inviter un ami par lien",
"откроет ссылку — и вы сразу друзья, обоим подарки":"il ouvre le lien — vous êtes amis, cadeaux pour tous les deux",
"Мой QR-код":"Mon code QR",
"Мой код дружбы":"Mon code d'ami",
"или код друга":"ou le code d'un ami",
"Сканировать QR-код":"Scanner un code QR",
"Вставь код: DUHF1…":"Colle le code : DUHF1…",
"Добавить по коду":"Ajouter par code",
"Достаточно, чтобы один из вас добавил код другого, — дружба станет взаимной.":"Il suffit que l'un de vous ajoute le code de l'autre — l'amitié deviendra mutuelle.",
"Друг у разлома нажал «Позвать друзей» и прислал код из 5 символов? Введи его — и в бой вместе, где бы ты ни был.":"Un ami près d'une faille a appuyé sur « Inviter des amis » et t'a envoyé un code de 5 caractères ? Saisis-le — et au combat ensemble, où que tu sois.",
"КОД":"CODE",
"пришло подарков: {0}":"cadeaux reçus : {0}",
"подарок каждому другу — раз в день":"un cadeau par ami — une fois par jour",
"Подарки от друзей":"Cadeaux de tes amis",
"за приглашение":"parrainage",
"Открыть":"Ouvrir",
"Подарок от друга сегодня получен":"Cadeau de cet ami reçu aujourd'hui",
