"Отправлен":"Envoyé",
"Пока никого — позови друга по ссылке или добавь его код ниже.":"Personne pour l'instant — invite un ami par lien ou ajoute son code ci-dessous.",
"Добавь меня в друзья в Духолове! «Меню → Друзья» → вставь код:\n{0}":"Ajoute-moi en ami dans Dukholov ! « Menu → Amis » → colle le code :\n{0}",
