"Не в друзьях":"Pas dans tes amis",
"Друзья обмениваются подарками и сражаются в поединках. Дружба растёт от подарков, поединков и совместных разломов.":"Les amis échangent des cadeaux et s'affrontent en duel. L'amitié grandit avec les cadeaux, les duels et les failles communes.",
