"Ловчий ещё не выбрал спутника.":"Ce Chasseur n'a pas encore choisi de compagnon.",
"Сильнейшие духи — для поединка":"Esprits les plus forts — pour le duel",
"{0} теперь твой друг!":"{0} est maintenant ton ami !",
"Заявка отправлена: когда {0} добавит тебя в ответ, вы станете друзьями":"Demande envoyée : quand {0} t'ajoutera en retour, vous serez amis",
