"Тапай — быстрая атака, она копит энергию; полная шкала — «Приём». Щиты берегут от приёмов соперника.":"Tape pour une attaque rapide, elle charge l'énergie ; jauge pleine — « Technique ». Les boucliers protègent des techniques adverses.",
