"Жетоны":"Jetons",
"жетоны обновятся через {0}":"jetons renouvelés dans {0}",
"Команда на бой":"Équipe de combat",
"Соперник — Ловчий с рейтингом ±{0} от твоего, а если такого нет — Ловчий Ордена. Рейтинг зависит от силы соперника · опыт — за первые {1} боёв дня":"Ton adversaire est un Chasseur dont le classement est à ±{0} du tien, ou un Chasseur de l’Ordre s’il n’y en a pas. Le classement dépend de la force de l’adversaire · XP pour les {1} premiers combats du jour",
"Общая таблица всех Ловчих появится, когда к игре подключат облачный сервер.":"Le classement général de tous les Chasseurs apparaîtra quand le jeu sera relié au serveur cloud.",
"Обновляется в реальном времени":"Mis à jour en temps réel",
"Ловчих":"Chasseurs",
