"Топ-50 сезона":"Top 50 de la saison",
"Нажми на Ловчего, чтобы открыть его карточку.":"Touche un Chasseur pour ouvrir sa fiche.",
"от {0}":"dès {0}",
"начало пути":"départ",
"Получено в этом сезоне":"Obtenu cette saison",
"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"La cote dépend de l'adversaire : battre un fort rapporte beaucoup, un faible peu ; perdre contre un faible coûte plus cher. Dans ta ligue, une victoire contre un égal vaut +{0}, une défaite −{1} ; plus la ligue est haute, plus on monte lentement. On peut descendre de ligue. La récompense de ligue est donnée une fois par saison. Au début d'une nouvelle saison, la cote au-delà de {2} est coupée de moitié, et l'Ordre offre un coffre pour la plus haute ligue de la saison passée. Dans les ligues « {3} », « {4} » et « {5} » — une amulette en plus.",
"<b>{0}-е место</b> из {1} в сезоне":"<b>{0}e place</b> sur {1} cette saison",
"Сыграй бой, чтобы попасть в таблицу":"Joue un combat pour entrer au classement",
"Карточка откроется после обновления сервера":"La fiche s'ouvrira après la mise à jour du serveur",
"Неизвестный ход":"Action inconnue",
"Слишком много ударов сразу":"Trop de coups à la fois",
"Неизвестный приём":"Technique inconnue",
"Этот приём не выучен":"Cette technique n'est pas apprise",
"Неверный приём":"Technique invalide",
"Этого духа не выпустить":"Impossible d'envoyer cet esprit",
"Бросай оберег, когда кольцо сжимается: «Отлично!» даёт больше опыта и шанс поимки.":"Lance le talisman quand le cercle rétrécit : un « Excellent ! » donne plus d'XP et de chances de capture.",
"Источники наполняются снова через несколько минут — прогулка по кругу приносит припасы.":"Les sources se remplissent de nouveau en quelques minutes — une balade en boucle rapporte des provisions.",
"Спутник ходит с тобой и находит эссенцию своего семейства.":"Le compagnon marche avec toi et trouve de l'essence de sa famille.",
"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"En Ligue s'affrontent de vrais Chasseurs : battre un adversaire fort rapporte plus de cote qu'un faible.",
"Разломы открываются у Капищ каждый час: собери команду из трёх духов.":"Les failles s'ouvrent près des Kapishche chaque heure : forme une équipe de trois esprits.",
"Сияющие духи редки — их выдают искры вокруг.":"Les esprits scintillants sont rares — des étincelles autour d'eux les trahissent.",
"Коконы греются шагами: одновременно можно греть три.":"Les cocons se réchauffent au fil des pas : tu peux en couver trois à la fois.",
"Ходи джойстиком: лёгкий наклон — шаг, до упора — бег. Километры для коконов считаются так же.":"Déplace-toi avec le joystick : une légère inclinaison pour marcher, à fond pour courir. Les kilomètres comptent pour les cocons tout pareil.",
"Атлас мира переносит в любой уголок Земли раз в полчаса, а Врата Перепутицы — сразу.":"L’Atlas du monde t’emmène n’importe où sur Terre une fois par demi-heure — les Portes du Grand Embrouillamini, tout de suite.",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"Les quêtes du jour se renouvellent à minuit, et le Coffre du jour attend qui les termine toutes.",
"Поставь защитника на Капище своего клана — он принесёт искры.":"Place un défenseur sur un Kapishche de ton clan — il te rapportera des étincelles.",
"Погода усиливает духов своей стихии: в дождь чаще встречаются водные.":"La météo renforce les esprits de son élément : sous la pluie, on croise plus d'esprits d'Eau.",
"Привяжи вход через Google, Яндекс или Telegram — прогресс не потеряется при смене телефона.":"Lie ta connexion à Google, Yandex ou Telegram — ta progression ne sera pas perdue si tu changes de téléphone.",
"Дари друзьям подарки каждый день — дружба растёт и приносит опыт.":"Offre des cadeaux à tes amis chaque jour — l'amitié grandit et rapporte de l'XP.",
