"У того Ловчего есть и другие способы входа — его прогресс останется доступен через них.":"Ce Chasseur a d’autres moyens de connexion — sa progression reste accessible par eux.",
"<b>У того Ловчего не останется других способов входа — его прогресс станет недоступен навсегда.</b>":"<b>Ce Chasseur n’aura plus aucun moyen de connexion — sa progression sera perdue pour toujours.</b>",
