"Готово: вход через {0} теперь у этого Ловчего":"C’est fait : la connexion via {0} appartient maintenant à ce Chasseur",
"Не удалось привязать — попробуй ещё раз":"Liaison impossible — réessaie",
"Вход уже привязан":"Connexion déjà liée",
"Вход через {0} привязан к Ловчему {1}.":"La connexion via {0} est liée au Chasseur {1}.",
"Можно перейти в ту учётную запись — тогда текущий гостевой прогресс на этом устройстве останется в прежней учётной записи, вернуться в неё будет нельзя. Или привязать этот вход к текущему Ловчему.":"Tu peux passer sur ce compte — ta progression d’invité sur cet appareil reste dans l’ancien compte, sans retour possible. Ou lier cette connexion à ton Chasseur actuel.",
"Можно перейти в ту учётную запись — текущий прогресс останется в своей. Или привязать этот вход к текущему Ловчему.":"Tu peux passer sur ce compte — ta progression actuelle reste dans le sien. Ou lier cette connexion à ton Chasseur actuel.",
