"Прогресс останется в учётной записи — вернуться в неё можно тем же входом. На этом устройстве начнётся новая гостевая игра.":"La progression reste dans le compte — tu pourras y revenir avec la même connexion. Une nouvelle partie invitée commencera sur cet appareil.",
