"Выйти из гостевой игры?":"Quitter la partie invitée ?",
"<b>Прогресс гостя пропадёт навсегда</b> — у гостя нет входа, чтобы вернуться.":"<b>La progression de l'invité sera perdue pour toujours</b> — un invité n'a pas de connexion pour revenir.",
