" На этой неделе {0}.":" Cette semaine : {0}.",
"Цель растёт с числом участников. Награду ступени получает каждый, кто внёс нужное число очков.":"L'objectif grandit avec le nombre de participants. Chacun ayant apporté assez de points reçoit la récompense du palier.",
"{0} распутана — ещё {1}":"{0} est démêlée — encore {1}",
"Орден собрал {0} осколков · до вехи {1}":"L'Ordre a rassemblé {0} éclats · encore {1} jusqu'au palier",
"Общий камень Ордена: каждая грань распутывает дорогу в один из миров":"La pierre commune de l'Ordre : chaque facette démêle la route d'un des mondes",
