"Обереги, мёд, источники и коконы":"Talismans, miel, sources et cocons",
"Кампания, задания дня и поручения источников":"Campagne, quêtes du jour et missions des sources",
"Лавка Ордена":"Boutique de l'Ordre",
"Обереги, мёд и живая вода":"Talismans, miel et Zhivaya Voda",
"Коды дружбы и ежедневные подарки":"Codes d’ami et cadeaux quotidiens",
"Награды за обычную игру":"Des récompenses en jouant",
"Бой командой из трёх духов с хранителем Разлома":"Combat d’une équipe de trois esprits contre le gardien de la Faille",
"Капища предков":"Les Kapishche des ancêtres",
"Поединки 3 на 3 с хранителями":"Duels 3 contre 3 avec les gardiens",
"Можно писать сообщения":"Tu peux écrire des messages",
"Освобождай захваченные источники":"Libère les sources capturées",
"Бои в реальном времени, рейтинг и лиги":"Combats en temps réel, cote et ligues",
"Клан своей мифологии — знамя над святилищами":"Un clan de ta mythologie — sa bannière flotte sur les sanctuaires",
"Продажа и покупка духов":"Vente et achat d'esprits",
"Шанс поимки ×1,5":"Chances de capture ×1,5",
"Шанс поимки ×2":"Chances de capture ×2",
"Поручения источников · {0}":"Missions des sources · {0}",
"Особые встречи и награды":"Rencontres et récompenses spéciales",
"Плащ «{0}»":"Cape « {0} »",
"Для облика Ловчего":"Pour l'apparence du Chasseur",
"Глаза «{0}»":"Yeux « {0} »",
"Пробуждение: звезда {0}":"Éveil : étoile {0}",
"Предел уровня духа +{0} за осколки Алатыря":"Limite de niveau de l'esprit +{0} contre des éclats d'Alatyr",
"Вершина пути":"Sommet de la voie",
"Максимальный уровень Ловчего":"Niveau maximal de Chasseur",
"Сегодня получено {0} опыта — полностью до {1}":"Aujourd'hui : {0} XP — en entier jusqu'à {1}",
"Сегодня получено {0} опыта — дальше вполовину до {1}":"Aujourd'hui : {0} XP — ensuite à moitié jusqu'à {1}",
"Сегодня получено {0} опыта — дальше на четверть":"Aujourd'hui : {0} XP — ensuite au quart",
"Опыт отдыха: следующие {0} опыта — вдвое":"XP de repos : les {0} prochains XP comptent double",
"За день опыт идёт полностью до {0}, дальше до {1} — вполовину, сверх — на четверть. Обучение и знаки Ордена дают опыт всегда полностью. За каждый день без игры копится опыт отдыха ({2}, не больше чем за {3} {4}): пока он есть, опыт вдвое.":"Chaque jour, l'XP compte en entier jusqu'à {0}, puis à moitié jusqu'à {1}, et au quart au-delà. Le tutoriel et les insignes de l'Ordre donnent toujours l'XP en entier. Chaque jour sans jouer accumule de l'XP de repos ({2}, pour {3} {4} au plus) : tant qu'il en reste, l'XP compte double.",
"Звание «{0}»":"Titre « {0} »",
"Ты здесь":"Tu es ici",
"Ты прошёл весь путь!":"Tu as parcouru toute la voie !",
"До {0} уровня — {1} опыта":"Jusqu'au niveau {0} — {1} XP",
"дальше: {0} на {1}":"ensuite : {0} au niveau {1}",
"Опыт дают поимки, источники, разломы, капища и задания. С уровнем растут и твои духи: их можно усиливать до уровня Ловчего +5.":"L'XP vient des captures, sources, failles, Kapishche et quêtes. Tes esprits grandissent avec ton niveau : tu peux les renforcer jusqu'au niveau du Chasseur +5.",
"С {0} уровня духов можно пробуждать: каждая звезда поднимает предел уровня духа ещё на {1}, до {2}.":"Dès le niveau {0}, les esprits peuvent être éveillés : chaque étoile relève leur limite de niveau de {1}, jusqu'à {2}.",
"Ищу настоящие места вокруг — Источники и Капища появятся через несколько секунд":"Recherche de vrais lieux alentour — Sources et Kapishche apparaîtront dans quelques secondes",
