"Там, где Алатырь дал трещину, из-под земли бьёт вода Перепутицы. У Источников Ловчие всех земель черпают обереги и припасы.":"Là où l’Alatyr s’est fendu, l’eau du Grand Embrouillamini jaillit de terre. Aux Sources, les Chasseurs de toutes les terres puisent talismans et provisions.",
