"Весь мир — твой":"Le monde entier est à toi",
"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"Le Grand Embrouillamini a emmêlé les routes du monde, et l’Ordre du Talisman a ouvert les Portes aux Chasseurs : choisis dans l’Atlas du monde n’importe quel coin de la Terre — c’est là que ta chasse commencera. Déplace-toi sur la carte avec le joystick, et rejoins de nouvelles contrées par l’Atlas. Le jeu n’a pas besoin de la position réelle de ton téléphone. Ta progression est stockée sur le serveur du jeu et n’est accessible qu’à toi ; le serveur vérifie chaque action, il faut donc Internet. Les lieux de la carte et la météo de la zone choisie sont chargés depuis OpenStreetMap et Open-Meteo (la météo peut être désactivée dans les réglages).",
"В путь":"En route",
"Уже играешь?":"Tu joues déjà ?",
"Войди — и твой прогресс откроется на этом устройстве":"Connecte-toi — et ta progression s'ouvrira sur cet appareil",
"Назови себя":"Donne ton nom",
