"Новое приложение":"Nouvelle appli",
"Игра переехала на свой сервер в России — <b>duholov.ru</b>. Для этого вышло новое приложение: его нужно установить заново.":"Le jeu a déménagé sur son propre serveur en Russie — <b>duholov.ru</b>. Une nouvelle appli est sortie pour cela : il faut la réinstaller.",
"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"Lie une connexion : Menu → Réglages → Compte (Google, Yandex, VK, Telegram ou e-mail). Sans cela, la progression d'invité ne sera pas transférée.",
"Удали это приложение.":"Supprime cette appli.",
